    /// <summary>
    /// Converts <paramref name="configValue"/> to <paramref name="targetType"/> and passes
    /// the result to <paramref name="setter"/>. Tries <see cref="Convert.ChangeType(object, Type, IFormatProvider)"/>
    /// first, then falls back to a public constructor accepting a single <see cref="string"/>.
    /// </summary>
    /// <returns><c>true</c> if conversion and setting succeeded; otherwise <c>false</c>.</returns>
    protected bool TryConvertAndSet(string configValue, Type targetType, Action<object?> setter)
    {
        try
        {
            // Attempt simple type conversion (e.g., int, bool, DateTime, etc.)
            // Use InvariantCulture for culture-neutral conversion
            object? convertedValue = Convert.ChangeType(configValue, targetType, CultureInfo.InvariantCulture);
            setter(convertedValue);
            return true;
        }
        catch
        {
            // If simple conversion fails, try to use a constructor that accepts a single string
            try
            {
                var constructor = targetType.GetConstructor(new[] { typeof(string) });
                if (constructor != null)
                {
                    object? instance = constructor.Invoke(new object[] { configValue });
                    setter(instance);
                    return true;
                }
            }
            catch
            {
                // silently ignore conversion errors and leave the field unchanged
            }
        }
        return false;
    }

