/// <summary>
/// Tracks assemblies that have already been processed to prevent duplicate loading.
/// </summary>
HashSet<Assembly> m_processedAssemblies = [];
private bool m_disposedValue;

/// <summary>
/// Loads default configuration values for all configurable types in the specified assembly.
/// </summary>
/// <param name="assembly">The assembly to scan for configurable types. Cannot be null.</param>
/// <remarks>
/// <para>
/// This method is idempotent - each assembly is processed only once, even if called
/// multiple times. Only assemblies and types marked with <see cref="ConfigurableAttribute"/>
/// are processed.
/// </para>
/// <para>
/// <b>Thread Safety:</b> While the assembly tracking is thread-safe, the actual field
/// assignments are not synchronized. This method should be called during single-threaded
/// initialization to avoid race conditions when setting static field values.
/// </para>
/// </remarks>
void LoadDefaults(Assembly assembly)
{
    if (DefaultConfig == null) return;
    // Thread-safe check-and-add to prevent processing an assembly multiple times
    lock (m_processedAssemblies)
    {
        if (m_processedAssemblies.Contains(assembly)) return;
        m_processedAssemblies.Add(assembly);
    }

    var assemblyAtt = assembly.GetCustomAttribute<ConfigurableAttribute>();
    if (assemblyAtt == null) return;

    foreach (var t in assembly.GetTypes())
    {
        var typeAtt = t.GetCustomAttribute<ConfigurableAttribute>();
        if (typeAtt == null) continue;
        LoadDefaults(t, DefaultConfig);
    }
}
/// <summary>
/// Loads configuration values into the configurable fields and properties of <paramref name="type"/>
/// using <see cref="GetConfigurableItems(Type)"/> for discovery and
/// <see cref="ConfigurableItem.TrySetValue"/> for conversion and assignment.
/// Configuration strings support <c>${key}</c> variable expansion.
/// </summary>
/// <param name="type">The type whose configurable members should be populated.</param>
/// <param name="config">The configuration source to read values from.</param>
/// <param name="instance">
/// If <c>null</c>, only static members are populated.
/// If non-null, only instance members on <paramref name="instance"/> are populated.
/// </param>
internal static void LoadDefaults(Type type, IConfiguration config, object? instance = null)
{
    foreach (var cv in GetConfigurableItems(type))
    {
        string path = cv.Path;
        var cval = config.GetExpandedValue(path);
        if (cval == null) continue;
        cv.TrySetValue(instance, cval);
    }
}

/// <summary>
/// Releases resources used by the <see cref="ConfigurableBinder"/>.
/// </summary>
/// <param name="disposing">
/// <c>true</c> if called from <see cref="IDisposable.Dispose"/>; <c>false</c> if called from a finalizer.
/// </param>
protected virtual void Dispose(bool disposing)
{
    if (!m_disposedValue)
    {
        if (disposing)
        {
            // Unregister the event handler to prevent memory leaks
            AppDomain.CurrentDomain.AssemblyLoad -= OnLoadDefaults;
        }
        m_disposedValue = true;
    }
}

