        /// </summary>
        /// <param name="expr">The expression string to evaluate.</param>
        /// <param name="uc">The current user context providing values for variables.</param>
        /// <returns>True if the expression evaluates to true; otherwise false.</returns>
        /// <exception cref="KeyNotFoundException">
        /// Thrown when the expression contains an unknown variable or constant.
        /// </exception>
        public static bool Eval(string expr, UserContext uc)
        {
            // Create a parser that resolves known variables/constants to their runtime values.
            var p = new SimpleExpressionParser((v) => (true,v switch
            {
                "false" => false,
                "true" => true,
                "IsAdmin" => uc.CurrentGroup == UserContext.AdminGroup,
                "is_admin" => uc.CurrentGroup == UserContext.AdminGroup,
                "user" => uc.CurrentUser,
                "group" => uc.CurrentGroup,
                _ => throw new KeyNotFoundException($"BCEE0DF4334E Invalid variable or constant '{v}'")
            })
            );
            p.DoParse(ref expr, out var val);
            return (bool)val;
        }

