public static void LoadJsonFromDir(ConfigurationManager cm, string basePath)
{
    if (System.IO.Directory.Exists(basePath))
    {
        // override with local.$ASPNETCORE_ENVIRONMENT.json
        var run_env = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT");
        if (!String.IsNullOrEmpty(run_env))
        {
            // load if runenv contain letters, numbers and underscore only. 
            if (!IsOnlyAlnumOrUnderscore().IsMatch(run_env))
            {
                run_env = null;
            }
        }
        VerboseLoadJson(cm, System.IO.Path.Combine(basePath, "appsettings.json"));
        if (run_env != null) VerboseLoadJson(cm, System.IO.Path.Combine(basePath, $"appsettings.{run_env}.json"));
        VerboseLoadJson(cm, System.IO.Path.Combine(basePath, "local.json"));
        if (run_env != null) VerboseLoadJson(cm, System.IO.Path.Combine(basePath, $"local.{run_env}.json"));
    }
}

/// <summary>
/// Loads all JSON files from a directory, sorted alphabetically, into the configuration manager.
/// </summary>
/// <param name="cm">The configuration manager to populate.</param>
/// <param name="basePath">Directory containing JSON files.</param>
public static void LoadJsonAllJsonFromDir(ConfigurationManager cm, string basePath)
{
    // Read all files from directory, sort by filename, i.e. user 00file.json 01logging.json convention to order loading.
    if (System.IO.Directory.Exists(basePath))
    {
        foreach (var json in Directory.GetFiles(basePath, "*.json").OrderBy(f => f))
        {
            VerboseLoadJson(cm, json);
        }
    }
}

