using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Microsoft.Extensions.Configuration;

class Probe {
  static void AddJsonFlat(ConfigurationManager cm, string path) {
    if (!File.Exists(path)) return;
    var doc = JsonDocument.Parse(File.ReadAllText(path));
    void Rec(JsonElement el, string prefix) {
      if (el.ValueKind == JsonValueKind.Object) {
        foreach (var p in el.EnumerateObject()) Rec(p.Value, prefix + (prefix.Length==0?p.Name:p.Name));
      } else {
        var key = prefix;
        cm.Add(key, el.ValueKind == JsonValueKind.String ? el.GetString() : el.GetRawText());
      }
    }
    // build keys with ':' separator
    var pairs = new List<KeyValuePair<string,string>>();
    void Rec2(JsonElement el, string prefix) {
      if (el.ValueKind == JsonValueKind.Object) {
        foreach (var p in el.EnumerateObject()) Rec2(p.Value, prefix.Length==0 ? p.Name : prefix + ":" + p.Name);
      } else {
        pairs.Add(new KeyValuePair<string,string>(prefix, el.ValueKind == JsonValueKind.String ? el.GetString() : el.GetRawText()));
      }
    }
    Rec2(doc.RootElement, "");
    cm.Add(pairs.ToArray());
  }
  static void Main(string[] args) {
    var baseDir = AppContext.BaseDirectory;
    var cm = new ConfigurationManager();
    AddJsonFlat(cm, baseDir + "appsettings.json");
    AddJsonFlat(cm, baseDir + "appsettings.Development.json");
    AddJsonFlat(cm, baseDir + "local.json");
    // AddEnvironmentVariables equivalent for the two relevant ones
    var env = new Dictionary<string,string>();
    foreach (var kv in System.Environment.GetEnvironmentVariables())
      env[kv.Key.ToString()] = kv.Value?.ToString();
    cm.Add(env.ToArray());
    IConfiguration config = cm;

    var asm = Assembly.LoadFrom(baseDir + "Bovis.Web.dll");
    var ifas = Assembly.LoadFrom(baseDir + "Bovis.Interfaces.dll");
